INSERT INTO dream_symbols (category, dream_object, chinese_char, kangxi_strokes, element, meaning_keyword, source) VALUES
  ('ครอบครัว (Family)', 'พ่อ / บิดา', '父', 4, 'ไฟ', 'อำนาจ, ผู้นำครอบครัว, การปกป้อง, ความรับผิดชอบ, ความสำเร็จ', 'original_457'),
  ('ครอบครัว', 'แม่ / มารดา', '母', 5, 'ดิน', 'ความรักความผูกพัน, การดูแลเอาใจใส่, บ้าน, ความอุดมสมบูรณ์', 'original_457'),
  ('ครอบครัว', 'ลูก / เด็กทารก', '子', 3, 'ไม้', 'การเริ่มต้นใหม่, ความบริสุทธิ์, ภาระที่น่ายินดี, โชคลาภเล็กๆ', 'original_457'),
  ('ครอบครัว', 'พี่ชาย / พี่สาว', '兄', 5, 'ไม้', 'ที่ปรึกษา, การช่วยเหลือ, มิตรภาพ, ความขัดแย้ง (ถ้าทะเลาะ)', 'original_457'),
  ('ครอบครัว', 'น้องชาย / น้องสาว', '弟', 7, 'ไม้', 'ความห่วงใย, ภาระที่ต้องดูแล, ความสนุกสนาน, ความวุ่นวาย', 'original_457'),
  ('ครอบครัว', 'ปู่ย่าตายาย', '祖', 10, 'ดิน', 'รากเหง้า, มรดก, ความคุ้มครอง, สุขภาพ, เรื่องเก่าๆ', 'original_457'),
  ('ครอบครัว', 'ญาติพี่น้อง', '親', 16, 'ไม้', 'ความสามัคคี, ปัญหาเรื่องเงิน, การรวมตัว, ข่าวสารในวงศ์ตระกูล', 'original_457'),
