  ('ความรัก', 'สามี / ภรรยา', '偶', 11, 'ดิน', 'ความมั่นคง, หุ้นส่วนชีวิต, หน้าที่ความรับผิดชอบ, ความอดทน', 'original_457'),
  ('ความรัก', 'ชู้ / มือที่สาม', '姦', 9, 'น้ำ', 'ความลับ, ปัญหาชู้สาว, การทรยศ, ความตื่นเต้นที่อันตราย', 'original_457'),
  ('สถานะทางสังคม (Roles)', 'เพื่อน / มิตรสหาย', '友', 4, 'ไม้', 'การสนับสนุน, สังคมใหม่, ข่าวสาร, การร่วมมือ', 'original_457'),
